+const VERSION_PATTERN =
+  /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
+
+function isNumeric(identifier: string): boolean {
+  return /^\d+$/.test(identifier);
+}
+
+function compareNumericIdentifiers(a: string, b: string): -1 | 0 | 1 {
+  const x = a.replace(/^0+/, "");
+  const y = b.replace(/^0+/, "");
+  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
+  if (x === y) return 0;
+  return x < y ? -1 : 1;
+}
+
+function comparePrereleases(a: string[], b: string[]): -1 | 0 | 1 {
+  const shared = Math.min(a.length, b.length);
+  for (let i = 0; i < shared; i++) {
+    const x = a[i];
+    const y = b[i];
+    const xNumeric = isNumeric(x);
+    const yNumeric = isNumeric(y);
+    if (xNumeric !== yNumeric) return xNumeric ? -1 : 1;
+    if (xNumeric && yNumeric) {
+      const order = compareNumericIdentifiers(x, y);
+      if (order !== 0) return order;
+    } else if (x !== y) {
+      return x < y ? -1 : 1;
+    }
+  }
+  if (a.length === b.length) return 0;
+  return a.length < b.length ? -1 : 1;
+}
